policies.inbound:








        {{graph-client-id}}
        api://{{graph-client-id}}









<set-variable name="pv-text" value="@{
    var body = context.Request.Body.As(preserveContent: true);
    return (string)body["input"] ?? "";
}" />

<set-variable name="pv-original-prompt" value="@((string)context.Variables.GetValueOrDefault("pv-text", ""))" />

<set-variable name="pv-prompt-called" value="@((string)context.Variables.GetValueOrDefault("pv-called", "0"))" />







<set-variable name="content-text"                 value="@((string)context.Variables.GetValueOrDefault("pv-text", ""))" />
<set-variable name="content-purview-blocked"      value="@((string)context.Variables.GetValueOrDefault("pv-blocked", "0") == "1" ? "true" : "false")" />
<set-variable name="content-purview-block-reason" value="@((string)context.Variables.GetValueOrDefault("pv-block-reason", "none"))" />





    <when condition="@((string)context.Variables.GetValueOrDefault("pv-blocked", "0") == "1")">


            1
            0
            1
            @((string)context.Variables.GetValueOrDefault("pv-block-reason", "PURVIEW_DLP_PROMPT"))
            0
            0
            @((string)context.Variables["pv-correlation-id"])
            @{
                var reason = context.Variables.GetValueOrDefault("pv-block-reason", "PURVIEW_DLP_PROMPT");
                var msg = reason.EndsWith("_UNKNOWN")
                    ? "Prompt could not be evaluated by Microsoft Purview DLP; failing closed."
                    : "Prompt blocked by Microsoft Purview DLP.";
                return "{\"blocked\":true,\"blockReason\":\"" + reason + "\",\"message\":\"" + msg + "\"}";
            }






@{
    var prompt = (string)context.Variables.GetValueOrDefault("pv-text", "");
    var envelope = new Newtonsoft.Json.Linq.JObject {
        ["inferenceConfig"] = new Newtonsoft.Json.Linq.JObject { ["max_new_tokens"] = 512 },
        ["messages"] = new Newtonsoft.Json.Linq.JArray {
            new Newtonsoft.Json.Linq.JObject {
                ["role"] = "user",
                ["content"] = new Newtonsoft.Json.Linq.JArray {
                    new Newtonsoft.Json.Linq.JObject { ["text"] = prompt }
                }
            }
        }
    };
    return envelope.ToString(Newtonsoft.Json.Formatting.None);
}

    application/json













    @(((DateTime)context.Variables["now"]).ToString("yyyyMMddTHHmmssZ"))


    @{
        var body = context.Request.Body.As(preserveContent: true);
        using (var sha256 = System.Security.Cryptography.SHA256.Create())
        {
            var hash = sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(body));
            return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }
    }


    @($"bedrock-runtime.{{bedrock-region}}.amazonaws.com")


    @{
        var accessKey = "{{aws-access-key}}";
        var secretKey = "{{aws-secret-key}}";
        var region    = "{{bedrock-region}}";
        var service   = "bedrock";
        var modelId   = "{{bedrock-model-id}}";
        var host      = $"bedrock-runtime.{region}.amazonaws.com";
        var method    = context.Request.Method;

        var amzDate   = ((DateTime)context.Variables["now"]).ToString("yyyyMMddTHHmmssZ");
        var dateStamp = ((DateTime)context.Variables["now"]).ToString("yyyyMMdd");

        var canonicalPath = $"/model/{System.Uri.EscapeDataString(modelId)}/invoke";
        var canonicalQueryString = "";

        var body = context.Request.Body.As(preserveContent: true);
        string hashedPayload;
        using (var sha256 = System.Security.Cryptography.SHA256.Create())
        {
            var hash = sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(body));
            hashedPayload = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }

        var canonicalHeaderList = new List {
            new[] { "content-type", "application/json" },
            new[] { "host", host },
            new[] { "x-amz-content-sha256", hashedPayload },
            new[] { "x-amz-date", amzDate }
        };
        var canonicalHeadersOrdered = canonicalHeaderList.OrderBy(h => h[0]).ToList();
        var canonicalHeaders = string.Join("\n", canonicalHeadersOrdered.Select(h => $"{h[0]}:{h[1].Trim()}")) + "\n";
        var signedHeaders    = string.Join(";", canonicalHeadersOrdered.Select(h => h[0]));

        var canonicalRequest = $"{method}\n{canonicalPath}\n{canonicalQueryString}\n{canonicalHeaders}\n{signedHeaders}\n{hashedPayload}";
        string hashedCanonicalRequest;
        using (var sha256 = System.Security.Cryptography.SHA256.Create())
        {
            var hash = sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(canonicalRequest));
            hashedCanonicalRequest = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }

        var credentialScope = $"{dateStamp}/{region}/{service}/aws4_request";
        var stringToSign    = $"AWS4-HMAC-SHA256\n{amzDate}\n{credentialScope}\n{hashedCanonicalRequest}";

        byte[] kSecret = System.Text.Encoding.UTF8.GetBytes("AWS4" + secretKey);
        byte[] kDate, kRegion, kService, kSigning;
        using (var h1 = new System.Security.Cryptography.HMACSHA256(kSecret))
            { kDate = h1.ComputeHash(System.Text.Encoding.UTF8.GetBytes(dateStamp)); }
        using (var h2 = new System.Security.Cryptography.HMACSHA256(kDate))
            { kRegion = h2.ComputeHash(System.Text.Encoding.UTF8.GetBytes(region)); }
        using (var h3 = new System.Security.Cryptography.HMACSHA256(kRegion))
            { kService = h3.ComputeHash(System.Text.Encoding.UTF8.GetBytes(service)); }
        using (var h4 = new System.Security.Cryptography.HMACSHA256(kService))
            { kSigning = h4.ComputeHash(System.Text.Encoding.UTF8.GetBytes("aws4_request")); }

        string signature;
        using (var hmac = new System.Security.Cryptography.HMACSHA256(kSigning))
        {
            var sigBytes = hmac.ComputeHash(System.Text.Encoding.UTF8.GetBytes(stringToSign));
            signature = BitConverter.ToString(sigBytes).Replace("-", "").ToLowerInvariant();
        }

        return $"AWS4-HMAC-SHA256 Credential={accessKey}/{credentialScope}, SignedHeaders={signedHeaders}, Signature={signature}";
    }
